// The service worker: Ksav, offline.
//
// This is the cheapest thing on the whole wishlist and the one with the largest
// reach. The wasm build is already a static site that runs the *real* Typst
// compiler in the browser, and documents already live in IndexedDB — so a
// manifest and this file are the entire difference between "a web page" and "an
// app on a bochur's phone that works on the bus with no signal". No server, no
// account, no money.
//
// Deliberately not a build-time precache manifest. Vite hashes its filenames, so
// a static list would have to be generated by a plugin and would go stale the
// moment anything is built by hand. Runtime caching needs no list: whatever the
// app actually asked for is what gets kept, which for a hashed asset is exactly
// right — the name changes when the contents do, so a cached entry can never be
// the wrong version of anything.
//
// The version comes from the registration URL (`sw.js?v=0.1.0`). A changed URL
// is what makes the browser treat this as a new worker at all, so taking the
// cache name from the same place means a release can never reuse the previous
// release's cache.

const VERSION = new URL(self.location).searchParams.get("v") || "dev";
const CACHE = `ksav-${VERSION}`;

// The shell, fetched on install so the very first offline load has something to
// open. Everything else arrives through `fetch` below as it is used.
const SHELL = ["/", "/index.html", "/manifest.webmanifest"];

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // Individually, and forgivingly: `addAll` rejects the whole install if any
      // one entry 404s, and an install that fails leaves the app with no worker
      // at all rather than with an imperfect one.
      await Promise.all(
        SHELL.map((url) => cache.add(url).catch(() => {})),
      );
      // Take over on the next load rather than the one after. Without this the
      // first visit after an update runs the *old* worker, which is how a user
      // ends up reporting a bug that was fixed a release ago.
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      for (const name of await caches.keys()) {
        if (name.startsWith("ksav-") && name !== CACHE) await caches.delete(name);
      }
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // A navigation is network-first: the writer should get the newest app when
  // there is a network, and the cached shell when there is not. Cache-first here
  // would pin somebody to whichever version they first opened.
  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          const fresh = await fetch(request);
          const cache = await caches.open(CACHE);
          cache.put("/index.html", fresh.clone());
          return fresh;
        } catch {
          return (await caches.match("/index.html")) ?? Response.error();
        }
      })(),
    );
    return;
  }

  // Everything else is cache-first. Vite's assets carry a content hash in their
  // name, so a hit is by construction the right bytes — and the 9 MB wasm chunk
  // is fetched exactly once ever rather than on every visit.
  event.respondWith(
    (async () => {
      const hit = await caches.match(request);
      if (hit) return hit;
      const fresh = await fetch(request);
      if (fresh.ok && fresh.type === "basic") {
        const cache = await caches.open(CACHE);
        cache.put(request, fresh.clone());
      }
      return fresh;
    })(),
  );
});
